//! 🧪️ Actual Flow arguments, original caller and canonical bytes preserve the independent JSON oracle.
use super::*;
use semio_framework_job::{OriginalJobFixtureCaller,OperationId,Generation};
use semio_framework_value::{RetainedCloneGrant,retirement::controlled::ControlledRetirement};
fn grant(v:&serde_json::Value)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:v["items"].as_u64().unwrap()as usize,maximum_copy_bytes:v["copy"].as_u64().unwrap()as usize,maximum_capacity_bytes:v["capacity"].as_u64().unwrap()as usize,maximum_release_bytes:v["release"].as_u64().unwrap()as usize,maximum_depth:v["depth"].as_u64().unwrap()as usize}}
fn arguments(row:&serde_json::Value)->FlowArguments{let mut payload=FlowPayloadWriter::default();payload.u32(row["width"].as_u64().unwrap()as u32);payload.u32(row["height"].as_u64().unwrap()as u32);payload.bytes(&row["mask"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as u8).collect::<Vec<_>>()).unwrap();payload.f64(row["threshold"].as_f64().unwrap());payload.f64(row["epsilon"].as_f64().unwrap());FlowArguments::preflight(2605,payload.finish()).unwrap()}
#[test]fn original_trace_returns_independent_json_and_closes_actual_owners(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();for row in law["cases"].as_array().unwrap(){let args=arguments(row);let stock=grant(&law["stock"]);let turn=grant(&law["turn"]);let mut caller=OriginalJobFixtureCaller::admit(OperationId(law["operation"].as_u64().unwrap()),Generation(law["generation"].as_u64().unwrap()),stock,||Some(1000),law["deadline"].as_u64().unwrap(),law["fuel"].as_u64().unwrap());let mut cursor=FlowTraceCursor::new();let mut output=None;
  for _ in 0..law["maxTurns"].as_u64().unwrap(){let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(turn,|cx|cursor.advance_original(&args,cx)));let receipt=caller.receipt();assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(receipt.retained_capacity_bytes,receipt.released_bytes));assert!(cursor.last_turn_work()<=1);match result.unwrap(){FlowFeatureStep::Complete(bytes)=>{output=Some(bytes);break;},FlowFeatureStep::Failed(_)=>panic!("Trace business fault must settle as funded JSON bytes"),_=>{}}}
  let output=output.expect("Finite original trace stock exhausted");let independent=serde_json::to_vec(&row["expected"]).unwrap();assert_eq!(serde_json::from_slice::<serde_json::Value>(&output).unwrap(),serde_json::from_slice::<serde_json::Value>(&independent).unwrap());cursor.begin_close();for _ in 0..law["maxTurns"].as_u64().unwrap(){if cursor.terminal_is_empty(){break;}let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(turn,|cx|cursor.close_original(cx)));result.unwrap();let receipt=caller.receipt();assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(receipt.retained_capacity_bytes,receipt.released_bytes));}assert!(cursor.terminal_is_empty());let mut output=ControlledRetirement::retain(output);for _ in 0..law["maxTurns"].as_u64().unwrap(){if output.terminal_is_empty(){break;}let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(turn,|cx|{let demand=output.next_demand(cx.retained_grant().maximum_copy_bytes)?;semio_framework_job::close_original_retained_step(cx,demand,|g|output.step(g))}));result.unwrap();let receipt=caller.receipt();assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(receipt.retained_capacity_bytes,receipt.released_bytes));}assert!(output.terminal_is_empty());
 }
}

#[test]fn original_trace_refuses_foreign_work_and_close_without_spending(){let law:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let args=arguments(&law["cases"][0]);let stock=grant(&law["stock"]);let turn=grant(&law["turn"]);let mut original=OriginalJobFixtureCaller::admit(OperationId(law["operation"].as_u64().unwrap()),Generation(law["generation"].as_u64().unwrap()),stock,||Some(1000),law["deadline"].as_u64().unwrap(),law["fuel"].as_u64().unwrap());let mut foreign=OriginalJobFixtureCaller::admit(OperationId(law["foreignOperation"].as_u64().unwrap()),Generation(law["generation"].as_u64().unwrap()),stock,||Some(1000),law["deadline"].as_u64().unwrap(),law["fuel"].as_u64().unwrap());let mut cursor=FlowTraceCursor::new();for _ in 0..6{original.turn(turn,|cx|cursor.advance_original(&args,cx)).unwrap();}let receipt=cursor.retained_receipt();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||foreign.turn(turn,|cx|cursor.advance_original(&args,cx)));assert!(result.is_err());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(cursor.last_turn_work(),law["deniedCpu"].as_u64().unwrap());assert_eq!(cursor.retained_receipt(),receipt);let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||foreign.turn(turn,|cx|cursor.close_original(cx)));assert!(result.is_err());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(cursor.last_turn_work(),law["deniedCpu"].as_u64().unwrap());assert_eq!(cursor.retained_receipt(),receipt);cursor.begin_close();for _ in 0..law["maxTurns"].as_u64().unwrap(){if cursor.terminal_is_empty(){break;}original.turn(turn,|cx|cursor.close_original(cx)).unwrap();}assert!(cursor.terminal_is_empty());}

#[test]fn original_flow_failure_preserves_primary_and_real_posting_refusal(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../../../../📡️protocol/⚠️failure/📐️.json")).unwrap();let stock=grant(&law["stock"]);let turn=grant(&law["turn"]);let close=grant(&law["closeTurn"]);let mut caller=OriginalJobFixtureCaller::admit(OperationId(law["operation"].as_u64().unwrap()),Generation(law["generation"].as_u64().unwrap()),stock,||Some(1000),law["deadline"].as_u64().unwrap(),law["fuel"].as_u64().unwrap());let mut values=Vec::<u64>::new();let source=Vec::<u64>::new();let(failure,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(turn,|cx|{let mut work=RetainedWorkLedger::new(cx.retained_grant());assert!(!work.contiguous(&mut values,1).unwrap());let receipt=work.receipt();cx.consume_retained(receipt).unwrap();cx.consume_fuel(1);let primary=source.canonical_tree_child(0).unwrap_err();cx.consume_fuel(1);let posting=cx.consume_retained(receipt).unwrap_err();FlowFailure::from_value(AbiErrorCode::Busy,primary).with_retained_progress(receipt).with_receipt_refusal(Some(posting))}));let receipt=caller.receipt();assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(receipt.retained_capacity_bytes,receipt.released_bytes));assert_eq!(receipt.retained_capacity_bytes,law["expectedAllocationBytes"].as_u64().unwrap()as usize);let independent=serde_json::json!({"primary":failure.message(),"postingRefusal":failure.receipt_refusal.is_some()});assert_eq!(serde_json::from_slice::<serde_json::Value>(&serde_json::to_vec(&independent).unwrap()).unwrap(),law["expected"]);
 fn close_owned<T:semio_framework_value::retirement::RetireOwned>(value:T,caller:&mut OriginalJobFixtureCaller,turn:RetainedCloneGrant,bound:u64){let mut owner=ControlledRetirement::retain(value);for _ in 0..bound{if owner.terminal_is_empty(){break;}let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(turn,|cx|{let d=owner.next_demand(cx.retained_grant().maximum_copy_bytes)?;semio_framework_job::close_original_retained_step(cx,d,|g|owner.step(g))}));result.unwrap();let receipt=caller.receipt();assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(receipt.retained_capacity_bytes,receipt.released_bytes));}assert!(owner.terminal_is_empty());}close_owned(failure,&mut caller,close,law["maxTurns"].as_u64().unwrap());close_owned(values,&mut caller,close,law["maxTurns"].as_u64().unwrap());
}

#[test]fn original_trace_keeps_encoded_output_before_funded_publication_and_close(){let law:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let args=arguments(&law["cases"][0]);let stock=grant(&law["stock"]);let turn=grant(&law["turn"]);let mut caller=OriginalJobFixtureCaller::admit(OperationId(law["operation"].as_u64().unwrap()),Generation(law["generation"].as_u64().unwrap()),stock,||Some(1000),law["deadline"].as_u64().unwrap(),law["fuel"].as_u64().unwrap());let mut cursor=FlowTraceCursor::new();let mut ready=false;for _ in 0..law["maxTurns"].as_u64().unwrap(){caller.turn(turn,|cx|cursor.advance_original(&args,cx)).unwrap();if cursor.phase==6&&cursor.output.is_some(){ready=true;break;}}assert!(ready);let pointer=cursor.output.as_ref().unwrap().as_ptr();let expected=serde_json::to_vec(&law["cases"][0]["expected"]).unwrap();assert_eq!(serde_json::from_slice::<serde_json::Value>(cursor.output.as_ref().unwrap()).unwrap(),serde_json::from_slice::<serde_json::Value>(&expected).unwrap());let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(RetainedCloneGrant{maximum_items:0,..turn},|cx|cursor.advance_original(&args,cx)));assert!(matches!(result.unwrap(),FlowFeatureStep::Yield));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(cursor.last_turn_work(),0);assert_eq!(cursor.output.as_ref().unwrap().as_ptr(),pointer);cursor.begin_close();for _ in 0..law["maxTurns"].as_u64().unwrap(){if cursor.terminal_is_empty(){break;}let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(turn,|cx|cursor.close_original(cx)));result.unwrap();let p=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));}assert!(cursor.terminal_is_empty());}

#[test]fn actual_tessellation_encoder_close_posts_real_cpu_and_denial_zero(){let law:serde_json::Value=serde_json::from_str(include_str!("../../🎟️close/📐️.json")).unwrap();let mut payload=FlowPayloadWriter::default();payload.bytes(law["input"]["handle"].as_str().unwrap().as_bytes()).unwrap();payload.f64(law["input"]["tolerance"].as_f64().unwrap());let mut args=FlowArguments::preflight(2599,payload.finish()).unwrap();let mut action=FlowAction2599{program:FlowProgramState::new(&args),receipt:Default::default(),work_units:0,identity:None,encoding:Some(ArtifactCanonicalJsonTreeWireCursor::new(semio_framework::MeshData::default())),output:None,complete:false};let mut caller=OriginalJobFixtureCaller::admit(OperationId(law["operation"].as_u64().unwrap()),Generation(law["generation"].as_u64().unwrap()),grant(&law["stock"]),||Some(1000),law["deadline"].as_u64().unwrap(),law["fuel"].as_u64().unwrap());let turn=grant(&law["turn"]);let before=action.work_units;let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(RetainedCloneGrant{maximum_items:0,..turn},|cx|FlowActionState::close_step(&mut action,&mut args,AbiWorkBudget{retained:cx.retained_grant(),byte_credit:0,now_ms:1000,deadline_ms:None,cancelled:false,interrupted:false})));assert!(!result.unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(action.work_units-before,0);let mut complete=false;for _ in 0..law["maxTurns"].as_u64().unwrap(){let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(turn,|cx|{let before=action.receipt;let cpu=action.work_units;let live=action.encoding.as_ref().is_some_and(|owner|!owner.terminal_is_empty());let result=FlowActionState::close_step(&mut action,&mut args,AbiWorkBudget{retained:cx.retained_grant(),byte_credit:0,now_ms:1000,deadline_ms:None,cancelled:false,interrupted:false});if live{assert_eq!(action.work_units-cpu,action.encoding.as_ref().unwrap().last_turn_work()as usize);}let after=action.receipt;let used=RetainedCloneProgress{copied_items:after.copied_items-before.copied_items,copied_bytes:after.copied_bytes-before.copied_bytes,retained_capacity_bytes:after.retained_capacity_bytes-before.retained_capacity_bytes,released_bytes:after.released_bytes-before.released_bytes};cx.consume_retained(used).unwrap();cx.consume_fuel((action.work_units-cpu)as u64);result}));let receipt=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(receipt.retained_capacity_bytes,receipt.released_bytes));if result.unwrap(){complete=true;break;}}assert!(complete);let actual=serde_json::json!({"paidCloseCpu":action.work_units>0,"deniedCloseCpu":0});assert_eq!(serde_json::from_slice::<serde_json::Value>(&serde_json::to_vec(&actual).unwrap()).unwrap(),law["expected"]);}

#[test]fn actual_tessellation_output_close_forwards_controlled_owner_cpu(){let law:serde_json::Value=serde_json::from_str(include_str!("../../🎟️close/📐️.json")).unwrap();let turn=grant(&law["turn"]);let mut caller=OriginalJobFixtureCaller::admit(OperationId(law["operation"].as_u64().unwrap()),Generation(law["generation"].as_u64().unwrap()),grant(&law["stock"]),||Some(1000),law["deadline"].as_u64().unwrap(),law["fuel"].as_u64().unwrap());let mut producer=ArtifactCanonicalJsonTreeWireCursor::new(semio_framework::MeshData::default());let mut output=None;for _ in 0..law["maxTurns"].as_u64().unwrap(){let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(turn,|cx|{cx.original_source_parent().unwrap();let result=producer.advance(cx.retained_grant());let receipt=match &result{Ok(step)=>step.progress,Err(error)=>error.retained_progress()};let posted=cx.consume_retained(receipt);cx.consume_fuel(producer.last_turn_work());posted.unwrap();result}));let receipt=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(receipt.retained_capacity_bytes,receipt.released_bytes));if let Some(bytes)=result.unwrap().output{output=Some(bytes);break;}}let output=output.expect("finite original typed encoder stock");let _:serde_json::Value=serde_json::from_slice(&output).unwrap();assert!(producer.terminal_is_empty());let mut payload=FlowPayloadWriter::default();payload.bytes(law["input"]["handle"].as_str().unwrap().as_bytes()).unwrap();payload.f64(law["input"]["tolerance"].as_f64().unwrap());let mut args=FlowArguments::preflight(2599,payload.finish()).unwrap();let mut action=FlowAction2599{program:FlowProgramState::new(&args),receipt:Default::default(),work_units:0,identity:None,encoding:None,output:Some(ControlledRetirement::retain(output)),complete:false};let mut done=false;for _ in 0..law["maxTurns"].as_u64().unwrap(){let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn(turn,|cx|{let before=action.receipt;let before_work=action.work_units;let live=action.output.as_ref().is_some_and(|owner|!owner.terminal_is_empty());let result=FlowActionState::close_step(&mut action,&mut args,AbiWorkBudget{retained:cx.retained_grant(),byte_credit:0,now_ms:1000,deadline_ms:None,cancelled:false,interrupted:false});if live{assert_eq!(action.work_units-before_work,action.output.as_ref().unwrap().last_turn_work()as usize);}let after=action.receipt;let used=RetainedCloneProgress{copied_items:after.copied_items-before.copied_items,copied_bytes:after.copied_bytes-before.copied_bytes,retained_capacity_bytes:after.retained_capacity_bytes-before.retained_capacity_bytes,released_bytes:after.released_bytes-before.released_bytes};cx.consume_retained(used).unwrap();cx.consume_fuel((action.work_units-before_work)as u64);result}));let receipt=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(receipt.retained_capacity_bytes,receipt.released_bytes));if result.unwrap(){done=true;break;}}assert!(done);assert_eq!(action.work_units>0,law["encodedOutputCloseCpu"].as_bool().unwrap());}
